import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"20、【觀】 坤下巽上","description":"子夏易傳 - 20、【觀】 坤下巽上","frontmatter":{"title":"20、【觀】 坤下巽上","description":"子夏易傳 - 20、【觀】 坤下巽上"},"headers":[],"relativePath":"classics/zixia/022.md","filePath":"classics/zixia/022.md"}'),i={name:"classics/zixia/022.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_20、【觀】-坤下巽上" tabindex="-1">20、【觀】 坤下巽上 <a class="header-anchor" href="#_20、【觀】-坤下巽上" aria-label="Permalink to “20、【觀】 坤下巽上”">​</a></h1><p>卦辭：觀，盥而不薦，有孚，顒若。</p><p>彖曰：大觀在上，順而巽，中正以觀天下。觀，盥而不薦，有孚顒若，下觀而化也。觀天之神道而四時不忒，聖人以神道設敎，而天下服矣。</p><p>子夏：觀上觀下也。下順上巽，觀上之風從而化之。上巽下坤，觀下之情而設敎也。剛德上行，為天下之大。觀得其中正大順，而巽以從之也。古者，先王之治天下，為風之首者，非他也。禮之謂歟敬，其禮之本，歟宗廟，其敬之大。歟盥，其祭之首。歟取，諸潔敬者也。禮也者，物得其履，而不謬也。措之天下無所不行，本於其敬也。敬發乎情者也。盡則誠信，誠積中而容作於外，施於人而人順也。敬之盡者，莫大於孝，莫大於尊，親愛之。故貴之。貴之故尊之。昔者周公郊祀后稷以配天，宗祀文王於明堂以配上帝。是以四海之內各以其職來祭，天下無不敬其親者，此不令而民化上矣。宗廟之始者，盥也。得其始，盡其敬，誠其孝，然後能事宗廟鬼神也。其先祭也，散齋三日，以定志。致齋三日，以一慮。其將祭也，恫恫乎，恐懼如將見之。詩云：明發不寐，有懷二人，思之深也。其敬齋也，先祭而告，慟哭反矣。況至於盥乎。盥者，祭之道可觀其首敬也。薦者，養之道，故盡其敬，竭其情，則能備物矣。所以假外物而成孝子之心也，非禮之本也，故不在於薦矣，觀其誠信顒若而已。民知其敬上也，聖人申其情，行其事，而成敎於天下。雖天子必有尊也。則神道報其情也。此先王設敎之端，而天下大服也。</p><p>象曰：風行地上，觀。</p><p>子夏：先王以省方，觀民設敎，草木從上之風而偃也。故先王察其方，所觀其俗性。不易其素履。則民自行其道也。</p><p>初六，童觀，小人無咎，君子吝。</p><p>象曰：初六，童觀，小人道也。</p><p>子夏：柔而無位，逺於大觀，童蒙而無所觀，小人之道也。</p><p>六二，闚觀，利女貞。</p><p>象曰：闚觀女貞，亦可醜也。</p><p>子夏：當大觀之時，不能逺於所觀，而顧覬覦為正，施於女子，守正則可矣。君子之醜也。</p><p>六三，觀我生進退。</p><p>象曰：觀我生進退，未失道也。</p><p>子夏：大觀在乎中正已，處下體之，上風化之，出而及於民，進其道也。柔以奉之，退而謙也。故觀我生之，風化進不淩上，退不廢職，或從正事，可謂不失其道矣。</p><p>六四，觀國之光，利用賔於王。</p><p>象曰：觀國之光，尚賔也。</p><p>子夏：履極臣位，順而承上，為上之巽，國之光也。煥乎可觀，利於用也。為王者之上賔。</p><p>九五，觀我生，君子無咎。</p><p>象曰：觀我生，觀民也。</p><p>子夏：為觀之尊，天下風化之首也。我之生化，備於民矣。觀其民有君子之風，乃天下無所歸，咎也。</p><p>上九，觀其生，君子無咎。</p><p>象曰：觀其生，志未平也。</p><p>子夏：過居無民之位，乘五之上，憂悔之地，志不得平也。亦在王敎而已自觀，有君子之風，乃無咎也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
